package org.mockito.internal.verification.argumentmatching;

import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;

import org.hamcrest.Matcher;
import org.hamcrest.StringDescription;
import org.mockito.internal.matchers.ContainsExtraTypeInformation;

@SuppressWarnings("unchecked")
public class ArgumentMatchingTool {

    /**
     * Suspiciously not matching arguments are those that don't much, the toString() representation is the same but types are different.
     */
    public Integer[] getSuspiciouslyNotMatchingArgsIndexes(List<Matcher> matchers, Object[] arguments) {
        if (matchers.size() != arguments.length) {
            return new Integer[0];
        }

        List<Integer> found = new LinkedList<Integer>();
        Iterator<Matcher> it = matchers.iterator();
        int idx = 0;
        while (it.hasNext()) {
            Matcher current = it.next();
            Object currentArg = arguments[idx];
            if (current instanceof ContainsExtraTypeInformation) {
                if (!safelyMatches(current, currentArg)) {
                    if (toStringEquals(current, currentArg)) {
                        if (!((ContainsExtraTypeInformation) current).typeMatches(currentArg)) {
                            found.add(idx);
                        }
                    }
                }
            }
            idx++;
        }
        return found.toArray(new Integer[0]);
    }

    private boolean safelyMatches(Matcher matcher, Object argument) {
        try {
            return matcher.matches(argument);
        } catch (Throwable e) {
            return false;
        }
    }

    private boolean toStringEquals(Matcher matcher, Object argument) {
        return argument.toString().equals(StringDescription.toString(matcher)) ;
    }
